// 1. CS students with GPA > 9.0
db.students.find(
  { department: 'CS', gpa: { $gt: 9.0 } },
  { name: 1, gpa: 1, _id: 0 }   // projection: show only name and gpa
)

// 2. Students who know Python (array contains)
db.students.find(
  { skills: 'Python' }  // MongoDB checks if array contains value
)

// 3. Students from Bangalore, sorted by GPA desc
db.students.find(
  { 'address.city': 'Bangalore' }  // dot notation for nested field
).sort({ gpa: -1 })

// 4. Students with exactly 3 skills
db.students.find(
  { skills: { $size: 3 } }
)

// 1. Update single field
db.students.updateOne(
  { name: 'Alice' },
  { $set: { gpa: 9.5 } }
)

// 2. Add to array (no duplicates)
db.students.updateOne(
  { name: 'Alice' },
  { $addToSet: { skills: 'TensorFlow' } }  // $push would allow duplicates
)

// 3. Remove from array
db.students.updateOne(
  { name: 'Bob' },
  { $pull: { skills: 'Docker' } }
)

// 4. Increment all CS students GPA by 0.1
db.students.updateMany(
  { department: 'CS' },
  { $inc: { gpa: 0.1 } }
)
// Note: MongoDB doesn't have built-in MIN/MAX cap in $inc
// For capping, use aggregation pipeline update:
db.students.updateMany(
  { department: 'CS' },
  [{ $set: { gpa: { $min: [{ $add: ['$gpa', 0.1] }, 10.0] } } }]
)

db.students.aggregate([
  // Stage 1: Group by department
  {
    $group: {
      _id: '$department',
      total_students: { $sum: 1 },
      avg_gpa: { $avg: '$gpa' },
      student_names: { $push: '$name' }
    }
  },
  // Stage 2: Filter departments with avg GPA > 8.5
  {
    $match: { avg_gpa: { $gt: 8.5 } }
  },
  // Stage 3: Round avg_gpa
  {
    $addFields: {
      avg_gpa: { $round: ['$avg_gpa', 2] }
    }
  },
  // Stage 4: Rename _id to department
  {
    $project: {
      department: '$_id',
      total_students: 1,
      avg_gpa: 1,
      student_names: 1,
      _id: 0
    }
  },
  // Stage 5: Sort by avg_gpa descending
  {
    $sort: { avg_gpa: -1 }
  }
])

// 1. Single field index
db.students.createIndex({ department: 1 })  // 1 = ascending

// 2. Compound index
db.students.createIndex({ department: 1, gpa: -1 })  // dept asc, gpa desc

// 3. Text index for full-text search
db.students.createIndex({ name: 'text', department: 'text' })

// Query using text index
db.students.find({ $text: { $search: 'Alice' } })

// View all indexes
db.students.getIndexes()

// Drop an index
db.students.dropIndex({ department: 1 })
